/**
 * Skeleton: a placeholder block shown while content loads.
 * Purpose: keeps the layout stable until data arrives. Generated by shadcn, then re-themed to Grove.
 *   Owner: design system. Shapes (text, card, row, image) and the shimmer: S2-T04.
 * Props: className sets the size and shape; native div props.
 * Responsive: sized by the caller. Accessibility: hidden from screen readers; mark the parent
 *   aria-busy while loading. The pulse stops under prefers-reduced-motion (globals.css).
 * States: loading only. Dependencies: cn.
 * Tests: controls.test.tsx; Design Lab "Feedback" (S2-T07).
 * UX reference: ds-feedback, loading states.
 */
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function Skeleton({ className, ...props }: Omit<ComponentProps<"div">, "ref">) {
  return (
    <div
      data-slot="skeleton"
      aria-hidden="true"
      className={cn("animate-pulse rounded-md bg-canvas-sunken", className)}
      {...props}
    />
  );
}

export { Skeleton };
